const PROCESSING_FEE = 5;
const BASE_PREMIUM_PER_ITEM = 100;

// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
// floating point (100 * 1.1 === 110.00000000000001).
const withFirstInsuranceSurcharge = (amount: number): number =>
  (amount * 11) / 10;

export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const results = scenario.steps.map((step) => {
    const basePremium = step.items.length * BASE_PREMIUM_PER_ITEM;
    const premium = withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
    return { premium };
  });

  return { results };
};
